import { useEffect, useId, useMemo, useRef, useSyncExternalStore } from "react";
import {
  Badge,
  Button,
  Heading,
  Image,
  Input,
  Pagination,
  Price,
  Select,
  Tab,
  Table,
  Tabs,
  Text,
} from "@paraxe/react";
import {
  createOrdersController,
  orderDate,
  orderFilters,
  orderItemCount,
  orderSorts,
  orderStatusLabels,
  orderStatusTone,
  ordersCSV,
  sampleOrders,
  type OrderFilter,
  type OrderRecord,
  type OrderSort,
  type Orders01Props,
} from "../shared/orders";
import "../shared/orders.css";
const columns = [
  { key: "number", label: "Order" },
  { key: "customer", label: "Customer" },
  { key: "status", label: "Status" },
  { key: "total", label: "Total", align: "end" as const },
];
export function Orders01({
  orders = sampleOrders,
  currency = "GBP",
  locale = "en-GB",
  title = "Every order. In view.",
  pageSize = 6,
  loading = false,
  error,
  retry,
  onOrderSelect,
}: Orders01Props & { onOrderSelect?: (order: OrderRecord) => void }) {
  const id = `orders-${useId()}`;
  const store = useMemo(
    () => createOrdersController(orders, pageSize),
    [pageSize],
  );
  const state = useSyncExternalStore(
    store.subscribe,
    store.getSnapshot,
    store.getSnapshot,
  );
  useEffect(() => store.replace(orders), [orders, store]);
  const view = store.view(),
    selected = view.selected,
    locked = loading || !!error;
  const detail = useRef<HTMLElement>(null),
    opener = useRef<HTMLButtonElement | null>(null);
  function open(order: OrderRecord, button: HTMLButtonElement) {
    if (locked) return;
    opener.current = button;
    store.select(order.id);
    onOrderSelect?.(order);
    requestAnimationFrame(() => {
      detail.current?.focus();
      if (window.matchMedia("(max-width: 1050px)").matches)
        detail.current?.scrollIntoView({ block: "start", behavior: "auto" });
    });
  }
  function close() {
    store.select(null);
    opener.current?.focus();
  }
  function download() {
    const url = URL.createObjectURL(
      new Blob(["\ufeff" + ordersCSV(view.filtered, currency)], {
        type: "text/csv;charset=utf-8",
      }),
    );
    const link = document.createElement("a");
    link.href = url;
    link.download = "orders.csv";
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }
  const money = (amount: number, label = "Amount") => (
    <span>
      {amount < 0 && "\u2212"}
      <Price
        amount={Math.abs(amount)}
        currency={currency}
        locale={locale}
        currentLabel={label}
      />
    </span>
  );
  const metrics = [
    ["Total orders", view.counts.all],
    ["Awaiting fulfilment", view.counts["to-pack"]],
    ["In transit", view.counts.shipped],
    ["Delivered", view.counts.delivered],
  ] as const;
  return (
    <section className="orders01" aria-labelledby={`${id}-title`}>
      <header className="orders01-heading">
        <div>
          <p className="orders01-eyebrow">Commerce / Order management</p>
          <Heading level="h1" id={`${id}-title`}>
            {title}
          </Heading>
          <Text>From the first confirmation to the final doorstep.</Text>
        </div>
        <Button
          variant="secondary"
          disabled={locked || !view.total}
          onActivate={download}
        >
          Export results <span aria-hidden="true">&#8599;</span>
        </Button>
      </header>
      <dl className="orders01-metrics">
        {metrics.map(([label, value]) => (
          <div key={label}>
            <dt>{label}</dt>
            <dd>
              {loading || error ? "\u2014" : value.toLocaleString(locale)}
            </dd>
          </div>
        ))}
      </dl>
      <div className="orders01-workbench">
        <section className="orders01-list" aria-labelledby={`${id}-list-title`}>
          <div className="orders01-list-heading">
            <Heading level="h2" id={`${id}-list-title`}>
              Order book
            </Heading>
            <span>Search, review, and follow through.</span>
          </div>
          <Tabs
            modelValue={state.filter}
            label="Filter orders by fulfilment"
            onModelValueChange={(value) =>
              !locked && store.filter(value as OrderFilter)
            }
          >
            {orderFilters.map((filter) => (
              <Tab
                key={filter.value}
                value={filter.value}
                disabled={locked}
                id={`${id}-tab-${filter.value}`}
                controls={`${id}-results`}
              >
                {filter.label}
                <span className="orders01-tab-count">
                  {view.counts[filter.value]}
                </span>
              </Tab>
            ))}
          </Tabs>
          <div
            id={`${id}-results`}
            role="tabpanel"
            aria-labelledby={`${id}-tab-${state.filter}`}
          >
            <div className="orders01-toolbar">
              <label className="orders01-search">
                <span className="orders01-sr">Search orders</span>
                <Input
                  name="orderSearch"
                  type="search"
                  placeholder="Search order, customer, or product"
                  modelValue={state.query}
                  disabled={locked}
                  onModelValueChange={(value) => store.query(value)}
                />
              </label>
              <label className="orders01-sort">
                <span>Sort by</span>
                <Select
                  name="orderSort"
                  modelValue={state.sort}
                  disabled={locked}
                  onModelValueChange={(value) => store.sort(value as OrderSort)}
                >
                  {orderSorts.map((sort) => (
                    <option key={sort.value} value={sort.value}>
                      {sort.label}
                    </option>
                  ))}
                </Select>
              </label>
            </div>
            {error ? (
              <div className="orders01-state" role="alert">
                <Heading level="h3">The order book is unavailable</Heading>
                <Text>{error}</Text>
                {retry && (
                  <Button
                    variant="secondary"
                    disabled={loading}
                    onActivate={retry}
                  >
                    Try again
                  </Button>
                )}
              </div>
            ) : (
              <>
                <p className="orders01-result-count" role="status">
                  {loading
                    ? "Loading orders..."
                    : `${view.total} ${view.total === 1 ? "order" : "orders"}${state.query ? " matching your search" : ""}`}
                </p>
                <Table
                  columns={columns}
                  rows={loading ? [] : view.rows}
                  rowKey="id"
                  caption="Orders. Activate an order number to review its details."
                  loading={loading}
                  loadingText="Loading orders..."
                  emptyText={
                    orders.length
                      ? "No orders match these filters."
                      : "There are no orders yet."
                  }
                  renderCell={(column, order) => {
                    if (column.key === "number")
                      return (
                        <>
                          <button
                            className="orders01-order-button"
                            type="button"
                            aria-controls={`${id}-detail`}
                            aria-expanded={state.selectedId === order.id}
                            onClick={(event) =>
                              open(order, event.currentTarget)
                            }
                          >
                            {order.number}
                          </button>
                          <span className="orders01-cell-note">
                            {orderDate(order.createdAt, locale)}
                          </span>
                        </>
                      );
                    if (column.key === "customer")
                      return (
                        <>
                          <strong className="orders01-customer">
                            {order.customer.name}
                          </strong>
                          <span className="orders01-cell-note">
                            {order.customer.email}
                          </span>
                        </>
                      );
                    if (column.key === "status")
                      return (
                        <>
                          <Badge variant={orderStatusTone(order.status)}>
                            {orderStatusLabels[order.status]}
                          </Badge>
                          <span className="orders01-cell-note">
                            {order.payment === "paid"
                              ? "Paid"
                              : order.payment === "pending"
                                ? "Payment pending"
                                : "Refunded"}
                          </span>
                        </>
                      );
                    return (
                      <>
                        {money(order.totals.total, "Order total")}
                        <span className="orders01-cell-note">
                          {orderItemCount(order)}{" "}
                          {orderItemCount(order) === 1 ? "item" : "items"}
                        </span>
                      </>
                    );
                  }}
                />
                {!loading &&
                  !view.total &&
                  (state.query || state.filter !== "all") && (
                    <div className="orders01-empty-action">
                      <Button variant="text" onActivate={store.clear}>
                        Clear filters
                      </Button>
                    </div>
                  )}
                {!loading && view.total > 0 && (
                  <footer className="orders01-pagination">
                    <span>
                      Showing {(view.page - 1) * view.pageSize + 1}–
                      {Math.min(view.page * view.pageSize, view.total)} of{" "}
                      {view.total}
                    </span>
                    <Pagination
                      label="Order pages"
                      currentPage={view.page}
                      pageSize={view.pageSize}
                      totalItems={view.total}
                      compact
                      onCurrentPageChange={store.page}
                    />
                  </footer>
                )}
              </>
            )}
          </div>
        </section>
        <section
          ref={detail}
          tabIndex={-1}
          className="orders01-detail"
          id={`${id}-detail`}
          aria-labelledby={`${id}-detail-title`}
          aria-busy={loading || undefined}
        >
          {locked || !selected ? (
            <div className="orders01-detail-empty">
              <p className="orders01-eyebrow">Order details</p>
              <Heading level="h2" id={`${id}-detail-title`}>
                {loading
                  ? "Loading the order book"
                  : error
                    ? "Details unavailable"
                    : "A closer look, right here."}
              </Heading>
              <Text>
                {loading
                  ? "Your orders will appear here shortly."
                  : error
                    ? "Restore the order book to review an order."
                    : "Choose an order number to review its items, delivery, and activity."}
              </Text>
            </div>
          ) : (
            <>
              <header className="orders01-detail-heading">
                <div>
                  <p className="orders01-eyebrow">Order details</p>
                  <Heading level="h2" id={`${id}-detail-title`}>
                    {selected.number}
                  </Heading>
                  <p className="orders01-detail-date">
                    {orderDate(selected.createdAt, locale, true)} UTC
                  </p>
                </div>
                <Button
                  variant="ghost"
                  size="small"
                  onActivate={close}
                  aria-label="Close order details"
                >
                  &#215;
                </Button>
              </header>
              <div className="orders01-detail-summary">
                <div>
                  <span>Order total</span>
                  {money(selected.totals.total, "Order total")}
                </div>
                <Badge variant={orderStatusTone(selected.status)}>
                  {orderStatusLabels[selected.status]}
                </Badge>
              </div>
              <div className="orders01-detail-section">
                <h3>
                  Items <span>({orderItemCount(selected)})</span>
                </h3>
                <ul className="orders01-lines">
                  {selected.lines.map((line) => (
                    <li key={line.id}>
                      <div className="orders01-line-image">
                        <Image
                          src={line.imageSrc}
                          alt={line.imageAlt}
                          fit="contain"
                          aspectRatio="square"
                          fallbackText="Product"
                        />
                      </div>
                      <div className="orders01-line-copy">
                        <strong>{line.name}</strong>
                        {line.variant && <span>{line.variant}</span>}
                        <span>Qty {line.quantity}</span>
                      </div>
                      {money(line.amount, "Line total")}
                    </li>
                  ))}
                </ul>
                <dl className="orders01-totals">
                  {(
                    [
                      ["Subtotal", selected.totals.subtotal],
                      ["Delivery", selected.totals.shipping],
                      ["Tax", selected.totals.tax],
                      ...(selected.totals.discount
                        ? [["Discount", -selected.totals.discount] as const]
                        : []),
                    ] as readonly (readonly [string, number])[]
                  ).map(([label, amount]) => (
                    <div key={label}>
                      <dt>{label}</dt>
                      <dd>{money(amount, label)}</dd>
                    </div>
                  ))}
                  <div className="orders01-total">
                    <dt>Total</dt>
                    <dd>{money(selected.totals.total, "Grand total")}</dd>
                  </div>
                </dl>
                <p className="orders01-payment-note">
                  {selected.payment === "paid"
                    ? "Payment received"
                    : selected.payment === "pending"
                      ? "Payment pending"
                      : "Payment refunded"}
                </p>
              </div>
              <div className="orders01-detail-section orders01-delivery">
                <div>
                  <h3>Customer</h3>
                  <strong>{selected.customer.name}</strong>
                  <a
                    href={`mailto:${encodeURIComponent(selected.customer.email)}`}
                  >
                    {selected.customer.email}
                  </a>
                </div>
                <div>
                  <h3>Delivery</h3>
                  <p>{selected.delivery.method}</p>
                  <address>
                    {selected.delivery.address.map((line, index) => (
                      <span key={index}>{line}</span>
                    ))}
                  </address>
                  {selected.delivery.trackingCode && (
                    <p className="orders01-tracking">
                      {selected.delivery.trackingHref ? (
                        <a href={selected.delivery.trackingHref}>
                          Track {selected.delivery.trackingCode} &#8599;
                        </a>
                      ) : (
                        <>Tracking: {selected.delivery.trackingCode}</>
                      )}
                    </p>
                  )}
                </div>
              </div>
              <div className="orders01-detail-section">
                <h3>Activity</h3>
                {selected.events.length ? (
                  <ol className="orders01-timeline">
                    {selected.events.map((event) => (
                      <li key={event.id}>
                        <strong>{event.title}</strong>
                        <time dateTime={event.at}>
                          {orderDate(event.at, locale, true)} UTC
                        </time>
                        {event.description && <p>{event.description}</p>}
                      </li>
                    ))}
                  </ol>
                ) : (
                  <p className="orders01-muted">
                    No activity has been supplied for this order.
                  </p>
                )}
              </div>
            </>
          )}
        </section>
      </div>
    </section>
  );
}

export type OrderStatus =
  | "unfulfilled"
  | "processing"
  | "shipped"
  | "delivered"
  | "cancelled";
export type OrderFilter =
  | "all"
  | "to-pack"
  | "shipped"
  | "delivered"
  | "cancelled";
export type OrderSort = "newest" | "oldest" | "total-high" | "total-low";
export interface OrderLine {
  id: string;
  name: string;
  variant?: string;
  quantity: number;
  amount: number;
  imageSrc?: string;
  imageAlt: string;
}
/** Amounts are app-supplied major currency units, never client-generated charges. */
export interface OrderRecord {
  id: string;
  number: string;
  createdAt: string;
  status: OrderStatus;
  payment: "paid" | "pending" | "refunded";
  customer: { name: string; email: string };
  lines: readonly OrderLine[];
  totals: {
    subtotal: number;
    shipping: number;
    tax: number;
    discount: number;
    total: number;
  };
  delivery: {
    method: string;
    address: readonly string[];
    trackingCode?: string;
    trackingHref?: string;
  };
  events: readonly {
    id: string;
    title: string;
    at: string;
    description?: string;
  }[];
}
export interface Orders01Props {
  orders?: readonly OrderRecord[];
  currency?: string;
  locale?: string;
  title?: string;
  pageSize?: number;
  loading?: boolean;
  error?: string;
  retry?: () => void;
}
export const orderFilters: readonly { value: OrderFilter; label: string }[] = [
  { value: "all", label: "All orders" },
  { value: "to-pack", label: "To fulfil" },
  { value: "shipped", label: "In transit" },
  { value: "delivered", label: "Delivered" },
  { value: "cancelled", label: "Cancelled" },
];
export const orderSorts: readonly { value: OrderSort; label: string }[] = [
  { value: "newest", label: "Newest first" },
  { value: "oldest", label: "Oldest first" },
  { value: "total-high", label: "Highest total" },
  { value: "total-low", label: "Lowest total" },
];
export const orderStatusLabels: Record<OrderStatus, string> = {
  unfulfilled: "Unfulfilled",
  processing: "Being prepared",
  shipped: "In transit",
  delivered: "Delivered",
  cancelled: "Cancelled",
};
export function orderStatusTone(status: OrderStatus) {
  return status === "delivered"
    ? "success"
    : status === "shipped"
      ? "brand"
      : status === "unfulfilled" || status === "processing"
        ? "warning"
        : "default";
}
export function orderDate(value: string, locale = "en-GB", withTime = false) {
  return new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
    year: "numeric",
    ...(withTime ? { hour: "2-digit", minute: "2-digit" } : {}),
    timeZone: "UTC",
  }).format(new Date(value));
}
export const orderItemCount = (order: OrderRecord) =>
  order.lines.reduce((sum, line) => sum + line.quantity, 0);
export const matchesOrderStatus = (order: OrderRecord, filter: OrderFilter) =>
  filter === "all" ||
  (filter === "to-pack"
    ? order.status === "unfulfilled" || order.status === "processing"
    : order.status === filter);
export function validateOrders(orders: readonly OrderRecord[]): OrderRecord[] {
  const ids = new Set<string>();
  return orders.map((order) => {
    if (
      !order.id ||
      ids.has(order.id) ||
      !order.number ||
      !Number.isFinite(Date.parse(order.createdAt)) ||
      !Object.prototype.hasOwnProperty.call(orderStatusLabels, order.status) ||
      !["paid", "pending", "refunded"].includes(order.payment)
    )
      throw Error("Orders require unique IDs, dates, and valid statuses.");
    ids.add(order.id);
    if (
      !order.customer?.name ||
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(order.customer.email)
    )
      throw Error("Each order requires a customer name and email.");
    const lineIds = new Set<string>();
    for (const line of order.lines) {
      if (
        !line.id ||
        lineIds.has(line.id) ||
        !line.name ||
        !Number.isSafeInteger(line.quantity) ||
        line.quantity < 1 ||
        !Number.isFinite(line.amount) ||
        line.amount < 0
      )
        throw Error("Invalid order line.");
      lineIds.add(line.id);
    }
    if (
      !order.lines.length ||
      !order.totals ||
      !["subtotal", "shipping", "tax", "discount", "total"].every(
        (key) =>
          Number.isFinite(order.totals[key as keyof typeof order.totals]) &&
          order.totals[key as keyof typeof order.totals] >= 0,
      )
    )
      throw Error("Orders require nonnegative app-supplied totals.");
    if (order.delivery.trackingHref) {
      const url = new URL(order.delivery.trackingHref);
      if (url.protocol !== "https:")
        throw Error("Tracking destinations must use HTTPS.");
    }
    const eventIds = new Set<string>();
    for (const event of order.events) {
      if (
        !event.id ||
        eventIds.has(event.id) ||
        !event.title ||
        !Number.isFinite(Date.parse(event.at))
      )
        throw Error("Invalid order activity.");
      eventIds.add(event.id);
    }
    return {
      ...order,
      customer: { ...order.customer },
      lines: order.lines.map((line) => ({ ...line })),
      totals: { ...order.totals },
      delivery: { ...order.delivery, address: [...order.delivery.address] },
      events: order.events
        .map((event) => ({ ...event }))
        .sort((a, b) => Date.parse(b.at) - Date.parse(a.at)),
    };
  });
}
export function filterOrders(
  orders: readonly OrderRecord[],
  query: string,
  filter: OrderFilter,
  sort: OrderSort,
) {
  const terms = query
    .trim()
    .toLocaleLowerCase("en-GB")
    .split(/\s+/)
    .filter(Boolean);
  return orders
    .filter(
      (order) =>
        matchesOrderStatus(order, filter) &&
        terms.every((term) =>
          [
            order.number,
            order.customer.name,
            order.customer.email,
            ...order.lines.map((line) => line.name),
          ]
            .join(" ")
            .toLocaleLowerCase("en-GB")
            .includes(term),
        ),
    )
    .sort((a, b) => {
      const difference =
        sort === "newest"
          ? Date.parse(b.createdAt) - Date.parse(a.createdAt)
          : sort === "oldest"
            ? Date.parse(a.createdAt) - Date.parse(b.createdAt)
            : sort === "total-high"
              ? b.totals.total - a.totals.total
              : a.totals.total - b.totals.total;
      return difference || a.id.localeCompare(b.id);
    });
}
export function ordersCSV(orders: readonly OrderRecord[], currency: string) {
  // Quotes alone do not stop spreadsheet formulas; prefix risky leading content.
  const cell = (input: unknown) => {
    let text = String(input);
    if (/^[\s]*[=+@-]/.test(text)) text = "'" + text;
    return '"' + text.replace(/"/g, '""') + '"';
  };
  return [
    [
      "Order",
      "Created UTC",
      "Customer",
      "Email",
      "Fulfilment",
      "Payment",
      "Items",
      "Total",
      "Currency",
    ],
    ...orders.map((order) => [
      order.number,
      order.createdAt,
      order.customer.name,
      order.customer.email,
      orderStatusLabels[order.status],
      order.payment,
      orderItemCount(order),
      order.totals.total,
      currency,
    ]),
  ]
    .map((row) => row.map(cell).join(","))
    .join("\r\n");
}
export function createOrdersController(
  initial: readonly OrderRecord[],
  initialPageSize = 6,
) {
  let records = validateOrders(initial);
  const pageSize = Number.isFinite(initialPageSize)
    ? Math.max(1, Math.min(50, Math.floor(initialPageSize)))
    : 6;
  let state: {
    query: string;
    filter: OrderFilter;
    sort: OrderSort;
    page: number;
    selectedId: string | null;
  } = {
    query: "",
    filter: "all",
    sort: "newest",
    page: 1,
    selectedId: filterOrders(records, "", "all", "newest")[0]?.id ?? null,
  };
  const listeners = new Set<() => void>();
  const result = () =>
    filterOrders(records, state.query, state.filter, state.sort);
  function view() {
    const filtered = result();
    const page = Math.min(
      state.page,
      Math.max(1, Math.ceil(filtered.length / pageSize)),
    );
    const rows = filtered.slice((page - 1) * pageSize, page * pageSize);
    return {
      filtered,
      rows,
      page,
      pageSize,
      total: filtered.length,
      selected: rows.find((order) => order.id === state.selectedId) ?? null,
      counts: Object.fromEntries(
        orderFilters.map((filter) => [
          filter.value,
          records.filter((order) => matchesOrderStatus(order, filter.value))
            .length,
        ]),
      ) as Record<OrderFilter, number>,
    };
  }
  function publish(next: Partial<typeof state>, reconcile = true) {
    state = { ...state, ...next };
    const current = view();
    state.page = current.page;
    if (reconcile && !current.rows.some((row) => row.id === state.selectedId))
      state.selectedId = current.rows[0]?.id ?? null;
    listeners.forEach((listener) => listener());
  }
  return {
    getSnapshot: () => state,
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    view,
    query(value: string) {
      publish({ query: value, page: 1 });
    },
    filter(value: OrderFilter) {
      if (orderFilters.some((filter) => filter.value === value))
        publish({ filter: value, page: 1 });
    },
    sort(value: OrderSort) {
      if (orderSorts.some((sort) => sort.value === value))
        publish({ sort: value, page: 1 });
    },
    page(value: number) {
      if (Number.isFinite(value))
        publish({ page: Math.max(1, Math.floor(value)) });
    },
    select(id: string | null) {
      if (id === null || view().rows.some((row) => row.id === id))
        publish({ selectedId: id }, false);
    },
    replace(next: readonly OrderRecord[]) {
      records = validateOrders(next);
